import { S3Client, PutObjectCommand, GetObjectCommand, DeleteObjectCommand } from '@aws-sdk/client-s3';
const s3 = new S3Client({});
export class S3Storage implements Storage {
  put(k, body, mime?) { return s3.send(new PutObjectCommand({ Bucket: '{{bucket}}', Key: k, Body: body, ContentType: mime })).then(() => {}); }
  async get(k) { return (await s3.send(new GetObjectCommand({ Bucket: '{{bucket}}', Key: k }))).Body as any; }
  delete(k) { return s3.send(new DeleteObjectCommand({ Bucket: '{{bucket}}', Key: k })).then(() => {}); }
  async url(k) { return `https://{{bucket}}.s3.amazonaws.com/${k}`; }
}
